create table if not exists public.airtime_cash_settings (id boolean primary key default true check(id), enabled boolean not null default false, receiving_number text not null default '', receiving_network text not null default 'MTN', fee_percent numeric(5,2) not null default 20 check(fee_percent>=0 and fee_percent<100), minimum_amount_naira integer not null default 100, maximum_amount_naira integer not null default 10000, updated_at timestamptz not null default now(), updated_by uuid references auth.users(id));
insert into public.airtime_cash_settings(id) values(true) on conflict(id) do nothing;
create table if not exists public.airtime_cash_requests (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id), sender_phone text not null, network text not null, amount_naira integer not null check(amount_naira>0), fee_percent numeric(5,2) not null, payout_naira integer not null check(payout_naira>0), payout_method text not null check(payout_method in ('wallet','bank')), bank_name text, bank_account_number text, bank_account_name text, bank_details_confirmed boolean not null default false, status text not null default 'pending' check(status in ('pending','processing','airtime_received','completed','rejected')), admin_note text, wallet_transaction_id uuid, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
alter table public.airtime_cash_settings enable row level security; alter table public.airtime_cash_requests enable row level security;
create policy "Authenticated read conversion settings" on public.airtime_cash_settings for select to authenticated using(true);
create policy "Customer read own conversion requests" on public.airtime_cash_requests for select to authenticated using(auth.uid()=user_id);
create policy "Customer submit conversion request" on public.airtime_cash_requests for insert to authenticated with check(auth.uid()=user_id and status='pending' and wallet_transaction_id is null);
create policy "Admin manage conversion settings" on public.airtime_cash_settings for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));
create policy "Admin manage conversion requests" on public.airtime_cash_requests for all to authenticated using(public.has_role(auth.uid(),'admin')) with check(public.has_role(auth.uid(),'admin'));